window.GalleryImagePicker={open(target,onChanged){
 const pid=data.project_id,tid=target.shot_id||target.id;
 if(shotFrameBusy(target.frameImages?.first?.job)){toast('请先停止当前首帧生成');return;}
 const dialog=document.createElement('dialog');dialog.style.cssText='width:min(620px,92vw);max-height:90vh;background:#192331;color:#dbe7f2;border:1px solid #405064;border-radius:12px;padding:22px';
 const state=shotFrameState(target,'first');let versions=(state.versions||[]).filter(v=>v.status==='completed'&&v.image_url&&!v.deleted_at&&!target.deletedShotFrameIds?.includes(v.id));
 dialog.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center"><h3>更改图片 · '+esc(tid)+'</h3><button data-close>关闭</button></div><label>素材类型<select data-kind><option value="first">分镜首帧</option><option value="last">分镜尾帧</option><option value="characters">人物</option><option value="scenes">场景</option></select></label><label>选择素材<select data-entity></select></label><label>图片版本<select data-version><option value="">请选择</option>'+versions.map((v,i)=>'<option value="'+esc(v.id)+'">V'+(i+1)+' · '+(v.width||'?')+' × '+(v.height||'?')+'</option>').join('')+'</select></label><img data-preview alt="所选图片预览" style="width:100%;height:280px;object-fit:contain;background:#090f16;margin:12px 0" hidden><div style="display:flex;gap:10px"><button data-use class="primary">采用所选图片</button><button data-upload>上传图片并采用</button><input data-file type="file" accept="image/png,image/jpeg,image/webp" hidden></div><p data-note role="status">原图片保留在历史版本中。</p>';
 document.body.append(dialog);dialog.onclose=()=>dialog.remove();dialog.querySelector('[data-close]').onclick=()=>dialog.close();const select=dialog.querySelector('[data-version]'),preview=dialog.querySelector('[data-preview]'),note=dialog.querySelector('[data-note]'),use=dialog.querySelector('[data-use]'),upload=dialog.querySelector('[data-upload]');
 const refresh=()=>{const im=versions.find(v=>v.id===select.value);preview.hidden=!im;preview.src=im?.image_url||'';use.disabled=!im;};select.value=state.activeId||'';select.onchange=refresh;refresh();
 const kind=dialog.querySelector('[data-kind]'),entity=dialog.querySelector('[data-entity]');
 const valid=v=>v&&!v.deleted_at&&v.status!=='failed'&&v.status!=='cancelled'&&(v.image_url||v.url);
 const list=(owner,type)=>{let out=[];const add=(v,label)=>{if(valid(v)&&!out.some(x=>x.id===(v.id||v.job_id)))out.push({...v,id:v.id||v.job_id,image_url:v.image_url||v.url,label});};if(type==='first'||type==='last'){(owner.frameImages?.[type]?.versions||[]).filter(v=>!owner.deletedShotFrameIds?.includes(v.id)).forEach((v,i)=>add(v,(type==='first'?'首帧':'尾帧')+' V'+(i+1)));}else if(type==='scenes'){[...(owner.sceneVersions||[]),...Object.values(owner.jobs||{}),...(owner.reference_states||[]).map(v=>({...v,id:v.version_id}))].forEach((v,i)=>add(v,v.name||'场景 V'+(i+1)));}else{[...(owner.contactSheets||[]),...(owner.singleViews||[]),...(owner.versions||[]),owner.identityPortrait,...(owner.multi||[]).flatMap(m=>Object.values(m.jobs||{}))].filter(Boolean).forEach((v,i)=>add(v,v.label||'人物 V'+(i+1)));}return out;};
 const entities=()=>kind.value==='characters'?data.characters||[]:kind.value==='scenes'?data.scenes||[]:data.shots||[];
 function loadVersions(){const o=entities().find(o=>(o.shot_id||o.character_id||o.scene_id||o.id)===entity.value);versions=o?list(o,kind.value):[];select.innerHTML='<option value="">请选择</option>'+versions.map(v=>'<option value="'+esc(v.id)+'">'+esc(v.label)+(v.width&&v.height?' · '+v.width+' × '+v.height:'')+'</option>').join('');select.value=versions.some(v=>v.id===state.activeId)?state.activeId:versions.at(-1)?.id||'';refresh();}
 function loadEntities(){entity.innerHTML=entities().map(o=>'<option value="'+esc(o.shot_id||o.character_id||o.scene_id||o.id)+'">'+esc((o.shot_id?o.shot_id+' · ':'')+(o.title||o.name||o.id))+'</option>').join('');if(kind.value==='first'||kind.value==='last')entity.value=tid;loadVersions();}kind.onchange=loadEntities;entity.onchange=loadVersions;loadEntities();
 async function importSource(source){const binding=source.frame_binding||source.frame_context;if(binding?.target_id===tid&&binding.position==='first'&&binding.project_id===pid)return source;const url=new URL(source.image_url,location.origin);if(url.origin!==location.origin||!/^\/api\/(front-image|contact-sheet)\/[a-f0-9-]{36}\/image$/.test(url.pathname))throw Error('不支持此图片来源');const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('源图片读取失败');const blob=await r.blob();if(blob.size>10*1024*1024)throw Error('图片超过10MB，请选择较小版本');const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('图片读取失败'));reader.readAsDataURL(blob);});await ensureProjectSaved();return frontFetch('/api/character-reference-upload',{resource_type:'frame',target_id:tid,position:'first',project_id:pid,image});}
 async function adopt(image){if(data.project_id!==pid||!data.shots.includes(target))throw Error('项目已变化，请重新打开');if(shotFrameBusy(state.job))throw Error('请先停止当前首帧生成');if(state.activeId!==image.id){state.versions??=[];if(!state.versions.some(v=>v.id===image.id))state.versions.push(image);state.activeId=image.id;state.job=image;state.sourceChoice='own';state.autoFromPrevious=false;state.needsReview=false;const b=image.frame_binding||image.frame_context,p=target.backgroundStatePolicy,l=data.scenes?.find(s=>(s.scene_id||s.id)===p?.scene_id)?.reference_states?.find(s=>s.state_id===p?.first_state_id);delete state.videoSourceApproval;if(b&&p?.enabled)state.videoSourceApproval={mode:'explicit_selected_frame',image_id:image.id,bound_layout_id:b.background_layout_id,bound_layout_version:b.background_layout_version,expected_layout_id:p.first_state_id,expected_layout_version:p.manual_image_id||l?.version_id,approved_at:new Date().toISOString(),reason:'User selected this image explicitly in gallery'};target.videoInvalidatedAt=new Date().toISOString();const i=data.shots.indexOf(target);if(i>0&&data.shotScript?.endpoint_generation_policy?.strategy==='next_shot_first')data.shots[i-1].videoInvalidatedAt=target.videoInvalidatedAt;save();await ensureProjectSaved();}dialog.close();onChanged();toast('已更改首帧，原版本和已有视频保留');}
 use.onclick=async()=>{use.disabled=true;try{const source=versions.find(v=>v.id===select.value);if(!source)throw Error('请选择图片');await adopt(await importSource(source));}catch(e){note.textContent=e.message;refresh();}};
 const file=dialog.querySelector('[data-file]');upload.onclick=()=>file.click();file.onchange=async()=>{const f=file.files[0];if(!f)return;try{if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>10*1024*1024)throw Error('请选择10MB以内的 PNG、JPEG 或 WebP 图片');upload.disabled=use.disabled=true;note.textContent='正在保存图片…';await ensureProjectSaved();const image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('图片读取失败'));r.readAsDataURL(f);});const job=await frontFetch('/api/character-reference-upload',{resource_type:'frame',target_id:tid,position:'first',project_id:pid,image});await adopt(job);}catch(e){note.textContent=e.message;upload.disabled=false;refresh();}finally{file.value='';}};dialog.showModal();
}};